381	// Per-tensor Prodigy step: d_lr is the current adaptive learning rate.
382	void launch_fused_prodigy_step(
383	    torch::Tensor param, torch::Tensor exp_avg, torch::Tensor exp_avg_sq,
384	    torch::Tensor s, torch::Tensor param_init, torch::Tensor grad,
385	    float lr, float d_lr, float beta1, float beta2,
386	    float weight_decay, float eps, float bc1, float bc2
387	) {
388	    auto d_t = torch::tensor({d_lr},
389	        torch::TensorOptions().device(param.device()).dtype(torch::kFloat32));
390	    auto r_partial = torch::zeros({1},
391	        torch::TensorOptions().device(param.device()).dtype(torch::kFloat32));
392	    auto s_partial = torch::zeros({1},
393	        torch::TensorOptions().device(param.device()).dtype(torch::kFloat32));
394	    launch_prodigy_step(param, exp_avg, exp_avg_sq, s, param_init, grad,
395	                        d_t, r_partial, s_partial, d_lr,
396	                        beta1, beta2, eps, weight_decay, bc1, bc2);
397	}
398	
399	// DLR reduction: numerator += <grad, param - param_init>,
400	// denominator += ||s|| * d + eps.
401	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_PRODIGY_MIN_BLOCKS)
402	prodigy_dlr_reduce_kernel(
403	    const float* __restrict__ grad, const float* __restrict__ param,
404	    const float* __restrict__ param_init, const float* __restrict__ s,
405	    float* __restrict__ numerator, float* __restrict__ denominator,
406	    float eps, int64_t N
407	) {
408	    float num_acc = 0.0f, den_acc = 0.0f;
409	    const int64_t stride = prim::grid_stride();
410	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
411	        num_acc += ::grokking::sm90::sg_sanitize_grad(grad[i]) *
412	                   (param[i] - param_init[i]);
413	        den_acc += fabsf(s[i]);
414	    }
415	    // Fused two-value block reduction → ONE atomicAdd per partial per block
416	    // (was a per-THREAD atomicAdd, i.e. blockDim.x * gridDim.x atomics).
417	    float num_block, den_block;
418	    prim::block_reduce_sum2_f32(num_acc, den_acc, num_block, den_block);
419	    if (threadIdx.x == 0) {
420	        atomicAdd(numerator, num_block);
421	        atomicAdd(denominator, den_block);
422	    }
423	}
424	
425	void launch_prodigy_dlr_reduce(
426	    torch::Tensor grad, torch::Tensor param, torch::Tensor param_init,
427	    torch::Tensor s, torch::Tensor numerator, torch::Tensor denominator,
428	    float eps
429	) {
430	    const int64_t N = grad.numel();
431	    if (N == 0) return;
432	    auto stream = at::cuda::getCurrentCUDAStream().stream();
433	    const int block = SG_TUNED_BLOCK_SIZE;
434	    const int grid = static_cast<int>(
435	        std::min<int64_t>(65535, (N + block - 1) / block));
436	    prodigy_dlr_reduce_kernel<<<grid, block, 0, stream>>>(
437	        grad.data_ptr<float>(), param.data_ptr<float>(),
438	        param_init.data_ptr<float>(), s.data_ptr<float>(),
439	        numerator.data_ptr<float>(), denominator.data_ptr<float>(),
440	        eps, N);
441	    SG_LAUNCH_CHECK(stream);
442	}
