444	// Multi-tensor fused reduce + step: accumulate the Prodigy D-estimate's
445	// PERSISTENT EMA numerator/denominator across all tensors, update d, then apply
446	// the Prodigy update to each.
447	//
448	// Canonical persistent-EMA estimator (Mishchenko & Defazio 2023 / prodigyopt):
449	// r_num_buf and s_den_buf are running EMAs that PERSIST across steps (carried in
450	// by the host from the Python optimizer). At step start they are decayed by
451	// beta3 = sqrt(beta2) — NOT zeroed — then this step's per-tensor reductions
452	//   r += Σ g·(p_init−p)·d²     (numerator, prodigy_partials_step)
453	//   s += Σ d²·|g|              (denominator L1, prodigy_partials_step)
454	// are atomic-added on top (so r_ema = beta3·r_ema + Σd²·…). d is then
455	//   d = max(d_prev, d_coef·r_ema/|s_ema|).
456	// This is the FIX for the instantaneous form (which zeroed r/s every step): the
457	// EMA averages post-memorization gradient-noise spikes over ~1/(1−beta3) steps
458	// so the `max()` no longer locks a single spike in → d PLATEAUS once the params
459	// stop drifting from init, instead of ratcheting up without bound (which had
460	// blown d past ~1e-1 and collapsed training back to random).
461	//
462	// prodigy.h's per-element/update device math is UNCHANGED (byte-identical): the
463	// EMA persistence + beta3 decay + d_coef scaling all live HERE in the host
464	// launcher, so the cross-backend math single-source hash does not move.
465	void launch_multi_tensor_prodigy_fused_reduce_step(
466	    std::vector<torch::Tensor>& params,
467	    std::vector<torch::Tensor>& grads,
468	    std::vector<torch::Tensor>& param_inits,
469	    std::vector<torch::Tensor>& exp_avgs,
470	    std::vector<torch::Tensor>& exp_avg_sqs,
471	    std::vector<torch::Tensor>& s_bufs,
472	    std::vector<float>& bc1s, std::vector<float>& bc2s,
473	    torch::Tensor d_lr_buf,
474	    torch::Tensor r_num_buf, torch::Tensor s_den_buf,
475	    float beta1, float beta2, float beta3, float lr, float wd, float eps,
476	    float d_coef
477	) {
478	    if (params.empty()) return;
479	    auto dev = params[0].device();
480	    float d_prev = d_lr_buf.item<float>();
481	
482	    auto stream = at::cuda::getCurrentCUDAStream().stream();
483	    const int block = SG_TUNED_BLOCK_SIZE;
484	
485	    // EMA decay of the PERSISTENT numerator/denominator (in place). The reduce
486	    // kernels below atomic-ADD this step's reduction on top, yielding
487	    //   r_ema <- beta3·r_ema + Σ d²·<g,p_init−p> ;  s_ema <- beta3·s_ema + Σ d²·|g|.
488	    r_num_buf.mul_(beta3);
489	    s_den_buf.mul_(beta3);
490	
491	    for (size_t i = 0; i < params.size(); i++) {
492	        const int64_t N = params[i].numel();
493	        if (N == 0) continue;
494	        const int grid = static_cast<int>(
495	        std::min<int64_t>(65535, (N + block - 1) / block));
496	        AT_DISPATCH_FLOATING_TYPES_AND2(
497	            at::ScalarType::Half, at::ScalarType::BFloat16,
498	            params[i].scalar_type(), "prodigy_mt_reduce", [&] {
499	                prodigy_reduce_kernel<scalar_t, scalar_t>
500	                    <<<grid, block, 0, stream>>>(
501	                    params[i].data_ptr<scalar_t>(),
502	                    param_inits[i].data_ptr<scalar_t>(),
503	                    grads[i].data_ptr<scalar_t>(),
504	                    d_prev,
505	                    r_num_buf.data_ptr<float>(),
506	                    s_den_buf.data_ptr<float>(), N);
507	                SG_LAUNCH_CHECK(stream);
508	            });
509	    }
510	
511	    // d = max(d_prev, d_coef·r_ema/|s_ema|). prodigy_update_d computes
512	    // max(d_prev, r/|s|) verbatim (prodigy.h, byte-identical), so d_coef is
513	    // folded by passing a SCALED numerator copy; the persistent r_num_buf keeps
514	    // the UNSCALED EMA (returned to Python). d_coef defaults to 1.0 (no-op).
515	    auto r_for_update = (d_coef == 1.0f)
516	        ? r_num_buf
517	        : (r_num_buf * d_coef).contiguous();
518	    prodigy_update_d_kernel<<<1, 1, 0, stream>>>(
519	        d_lr_buf.data_ptr<float>(),
520	        r_for_update.data_ptr<float>(),
521	        s_den_buf.data_ptr<float>(), d_prev);
522	    SG_LAUNCH_CHECK(stream);
523	
524	    for (size_t i = 0; i < params.size(); i++) {
525	        const int64_t N = params[i].numel();
526	        if (N == 0) continue;
527	        const int grid = static_cast<int>(
528	        std::min<int64_t>(65535, (N + block - 1) / block));
529	        AT_DISPATCH_FLOATING_TYPES_AND2(
530	            at::ScalarType::Half, at::ScalarType::BFloat16,
531	            params[i].scalar_type(), "prodigy_mt_apply", [&] {
532	                prodigy_apply_kernel<scalar_t, scalar_t, SG_TUNED_UNROLL>
533	                    <<<grid, block, 0, stream>>>(
534	                    params[i].data_ptr<scalar_t>(),
535	                    exp_avgs[i].data_ptr<float>(),
536	                    exp_avg_sqs[i].data_ptr<float>(),
537	                    s_bufs[i].data_ptr<float>(),
538	                    grads[i].data_ptr<scalar_t>(),
539	                    d_lr_buf.data_ptr<float>(),
540	                    beta1, beta2, eps, wd, bc1s[i], bc2s[i], N);
541	                SG_LAUNCH_CHECK(stream);
542	            });
543	    }
544	}
