58	template <typename GradT, int UNROLL>
59	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_MUON_MIN_BLOCKS)
60	muon_momentum_normalize_kernel(
61	    float* buf, float* X, const GradT* grad,
62	    float momentum, float inv_norm, int64_t N
63	) {
64	    const int64_t stride = prim::grid_stride() * UNROLL;
65	    const int64_t base0 = prim::grid_stride_index() * UNROLL;
66	    for (int64_t base = base0; base < N; base += stride) {
67	        #pragma unroll
68	        for (int u = 0; u < UNROLL; ++u) {
69	            const int64_t i = base + u;
70	            if (i < N) {
71	                SG_SANITIZE_GRAD_INPLACE(grad, i);
72	                muon_momentum_normalize_step(buf, X, grad, momentum, inv_norm, i);
73	            }
74	        }
75	    }
76	}
77	
78	// FP32 vec4 momentum-normalize: float4 traffic, canonical step CALLED 4×.
79	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_MUON_MIN_BLOCKS)
80	muon_momentum_normalize_kernel_vec4_fp32(
81	    float4* buf4, float4* X4, const float4* grad4,
82	    float momentum, float inv_norm, int64_t N4
83	) {
84	    const int64_t stride = prim::grid_stride();
85	    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
86	        float4 b = prim::ld_f32v4(buf4 + i);
87	        float4 x = prim::ld_f32v4(X4 + i);
88	        float4 g = prim::ldg_f32v4(grad4 + i);
89	        ::grokking::sm90::sg_sanitize_grad4(g);
90	        #pragma unroll
91	        for (int u = 0; u < 4; ++u) {
92	            muon_momentum_normalize_step(&b.x, &x.x, &g.x, momentum, inv_norm, u);
93	        }
94	        prim::st_f32v4(buf4 + i, b);
95	        prim::st_f32v4(X4 + i, x);
96	    }
97	}
