99	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_MUON_MIN_BLOCKS)
100	muon_ns_combine_kernel(
101	    float* Y, const float* X, const float* AX, const float* AAX,
102	    float a, float b, float c, int64_t N
103	) {
104	    const int64_t stride = prim::grid_stride();
105	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
106	        muon_ns_combine_step(Y, X, AX, AAX, a, b, c, i);
107	    }
108	}
