110	template <typename ParamT, int UNROLL>
111	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_MUON_MIN_BLOCKS)
112	muon_update_kernel(
113	    ParamT* param, const float* orth,
114	    float neg_lr_scale, float decay_factor, int64_t N
115	) {
116	    const int64_t stride = prim::grid_stride() * UNROLL;
117	    const int64_t base0 = prim::grid_stride_index() * UNROLL;
118	    for (int64_t base = base0; base < N; base += stride) {
119	        #pragma unroll
120	        for (int u = 0; u < UNROLL; ++u) {
121	            const int64_t i = base + u;
122	            if (i < N) {
123	                muon_update_step(param, orth, neg_lr_scale, decay_factor, i);
124	            }
125	        }
126	    }
127	}
128	
129	// FP32 vec4 update: float4 traffic, canonical muon_update_step CALLED 4×.
130	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_MUON_MIN_BLOCKS)
131	muon_update_kernel_vec4_fp32(
132	    float4* param4, const float4* orth4,
133	    float neg_lr_scale, float decay_factor, int64_t N4
134	) {
135	    const int64_t stride = prim::grid_stride();
136	    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
137	        float4 p = prim::ld_f32v4(param4 + i);
138	        float4 o = prim::ldg_f32v4(orth4 + i);
139	        #pragma unroll
140	        for (int u = 0; u < 4; ++u) {
141	            muon_update_step(&p.x, &o.x, neg_lr_scale, decay_factor, u);
142	        }
143	        prim::st_f32v4(param4 + i, p);
144	    }
145	}
