147	void launch_muon_momentum_normalize(
148	    torch::Tensor buf, torch::Tensor X, torch::Tensor grad,
149	    float momentum, float inv_norm
150	) {
151	    const int64_t N = buf.numel();
152	    if (N == 0) return;
153	    auto stream = at::cuda::getCurrentCUDAStream().stream();
154	
155	    // §6.1: keep the Muon momentum buffer L2-resident across the step.
156	    prim::L2PersistScope l2(stream, buf.data_ptr(), buf.nbytes());
157	
158	    const int block = SG_TUNED_BLOCK_SIZE;
159	    const int grid = static_cast<int>(
160	        std::min<int64_t>(65535, (N + block - 1) / block));
161	
162	    if (SG_TUNED_VEC_WIDTH == 4 && grad.scalar_type() == torch::kFloat32 &&
163	        prim::is_vec4_alignable(buf.data_ptr(), N) &&
164	        prim::is_vec4_alignable(X.data_ptr(), N) &&
165	        prim::is_vec4_alignable(grad.data_ptr(), N)) {
166	        const int64_t N4 = N / 4;
167	        const int grid4 = static_cast<int>(
168	            std::min<int64_t>(65535, (N4 + block - 1) / block));
169	        muon_momentum_normalize_kernel_vec4_fp32<<<grid4, block, 0, stream>>>(
170	            reinterpret_cast<float4*>(buf.data_ptr<float>()),
171	            reinterpret_cast<float4*>(X.data_ptr<float>()),
172	            reinterpret_cast<const float4*>(grad.data_ptr<float>()),
173	            momentum, inv_norm, N4);
174	        SG_LAUNCH_CHECK(stream);
175	        return;
176	    }
177	
178	    AT_DISPATCH_FLOATING_TYPES_AND2(
179	        at::ScalarType::Half, at::ScalarType::BFloat16,
180	        grad.scalar_type(), "muon_momentum_normalize", [&] {
181	            muon_momentum_normalize_kernel<scalar_t, SG_TUNED_UNROLL>
182	                <<<grid, block, 0, stream>>>(
183	                buf.data_ptr<float>(), X.data_ptr<float>(),
184	                grad.data_ptr<scalar_t>(),
185	                momentum, inv_norm, N);
186	            SG_LAUNCH_CHECK(stream);
187	        });
188	}
