208	void launch_muon_update(
209	    torch::Tensor param, torch::Tensor orth,
210	    float neg_lr_scale, float decay_factor
211	) {
212	    const int64_t N = param.numel();
213	    if (N == 0) return;
214	    auto stream = at::cuda::getCurrentCUDAStream().stream();
215	    const int block = SG_TUNED_BLOCK_SIZE;
216	    const int grid = static_cast<int>(
217	        std::min<int64_t>(65535, (N + block - 1) / block));
218	
219	    if (SG_TUNED_VEC_WIDTH == 4 && param.scalar_type() == torch::kFloat32 &&
220	        prim::is_vec4_alignable(param.data_ptr(), N) &&
221	        prim::is_vec4_alignable(orth.data_ptr(), N)) {
222	        const int64_t N4 = N / 4;
