225	        muon_update_kernel_vec4_fp32<<<grid4, block, 0, stream>>>(
226	            reinterpret_cast<float4*>(param.data_ptr<float>()),
227	            reinterpret_cast<const float4*>(orth.data_ptr<float>()),
