111	// Meta-net forward: mu[i] = phi(grad[i], sharpness[i]); smart_grad = grad + alpha*mu
112	template <typename GradT>
113	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK11_MIN_BLOCKS)
114	sg11_mu_metanet_kernel(
115	    float* mu, const GradT* grad, const float* sharpness,
116	    float* smart_grad, float alpha,
117	    const float* W1, const float* b1, const float* W2, float b2_scalar,
118	    float rescale, int64_t N
119	) {
120	    __shared__ float sW1[SG11_H * 2];
121	    __shared__ float sb1[SG11_H];
122	    __shared__ float sW2[SG11_H];
123	    sg11_stage_phi_weights<SG11_H>(W1, b1, W2, sW1, sb1, sW2);
124	
125	    const int64_t stride = prim::grid_stride();
126	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
127	        SG_SANITIZE_GRAD_INPLACE(grad, i);
128	        float g = static_cast<float>(grad[i]);
129	        float s = sharpness[i];
130	        float phi = sg11_phi_forward<SG11_H>(g, s, sW1, sb1, sW2, b2_scalar) * rescale;
131	        mu[i] = phi;
132	        smart_grad[i] = g + alpha * phi;
133	    }
134	}
