202	// SAM perturbation: param += rho_over_norm * grad
203	template <typename ParamT>
204	__global__ void sg11_sam_perturb_kernel(
205	    ParamT* param, const ParamT* grad, float rho_over_norm, int64_t N
206	) {
207	    const int64_t stride = prim::grid_stride();
208	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
