105	template <typename ParamT, typename GradT, int UNROLL>
106	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_SUPERGROK15_MIN_BLOCKS)
107	sg15_sweep_b_kernel(
108	    ParamT* param, float* exp_avg, float* exp_avg_sq,
109	    const GradT* grad, const float* mu,
110	    float gate_global, float alpha_base, float alpha_max,
111	    float lr, float beta1, float beta2, float eps, float wd,
112	    float bc1, float bc2, int64_t N
113	) {
114	    const int64_t stride = prim::grid_stride() * UNROLL;
115	    const int64_t base0 = prim::grid_stride_index() * UNROLL;
116	    for (int64_t base = base0; base < N; base += stride) {
117	        #pragma unroll
118	        for (int u = 0; u < UNROLL; ++u) {
119	            const int64_t i = base + u;
120	            if (i < N) {
121	                SG_SANITIZE_GRAD_INPLACE(grad, i);
122	                sg15_sweep_b_step(param, exp_avg, exp_avg_sq, grad, mu,
123	                                  gate_global, alpha_base, alpha_max,
124	                                  lr, beta1, beta2, eps, wd, bc1, bc2, i);
125	            }
126	        }
127	    }
128	}
