272	// SAM perturbation: param += rho_over_norm * grad
273	template <typename ParamT>
274	__global__ void sg15_sam_perturb_kernel(
275	    ParamT* param, const ParamT* grad, float rho_over_norm, int64_t N
276	) {
277	    const int64_t stride = prim::grid_stride();
278	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
279	        float p = static_cast<float>(param[i]);
280	        float g = ::grokking::sm90::sg_sanitize_grad(static_cast<float>(grad[i]));
281	        param[i] = static_cast<ParamT>(p + rho_over_norm * g);
282	    }
283	}
