285	void launch_sam_perturb(
286	    torch::Tensor param, torch::Tensor grad, float rho_over_norm
287	) {
288	    const int64_t N = param.numel();
289	    if (N == 0) return;
290	    auto stream = at::cuda::getCurrentCUDAStream().stream();
291	    const int block = SG_TUNED_BLOCK_SIZE;
292	    const int grid = static_cast<int>(
293	        std::min<int64_t>(65535, (N + block - 1) / block));
294	    AT_DISPATCH_FLOATING_TYPES_AND2(
295	        at::ScalarType::Half, at::ScalarType::BFloat16,
296	        param.scalar_type(), "sg15_sam_perturb", [&] {
297	            sg15_sam_perturb_kernel<scalar_t><<<grid, block, 0, stream>>>(
298	                param.data_ptr<scalar_t>(), grad.data_ptr<scalar_t>(),
299	                rho_over_norm, N);
300	            SG_LAUNCH_CHECK(stream);
301	        });
302	}
