927	// Replaces N CPU syncs with one (torch::stack of bufs[i].norm()).
928	// ---------------------------------------------------------------------
929	
930	void muon_fused_step(
931	 std::vector<torch::Tensor>& params,
932	 std::vector<torch::Tensor>& grads,
933	 std::vector<torch::Tensor>& bufs,
934	 float momentum, float lr, float wd, int ns_steps
935	) {
936	 check_params_grads(params, grads, "muon_fused_step");
937	 check_list_len(bufs, params.size(), "bufs", "muon_fused_step");
938	 constexpr float NS_A = 3.4445f;
939	 constexpr float NS_B = -4.7750f;
940	 constexpr float NS_C = 2.0315f;
941	
942	 std::vector<torch::Tensor> norm_tensors;
943	 std::vector<size_t> valid_indices;
944	 norm_tensors.reserve(params.size());
945	 valid_indices.reserve(params.size());
946	 for (size_t i = 0; i < params.size(); i++) {
947	 if (!grads[i].defined() || grads[i].numel() == 0) continue;
948	 bufs[i].mul_(momentum).add_(grads[i]);
949	 norm_tensors.push_back(bufs[i].norm());
950	 valid_indices.push_back(i);
951	 }
952	 if (norm_tensors.empty()) return;
953	
954	 auto norms_stacked = torch::stack(norm_tensors).cpu();
955	 auto* norms_ptr = norms_stacked.data_ptr<float>();
956	
957	 for (size_t vi = 0; vi < valid_indices.size(); vi++) {
958	 size_t i = valid_indices[vi];
959	 auto& p = params[i];
960	 auto& buf = bufs[i];
961	
962	 float buf_norm = norms_ptr[vi] + 1e-7f;
963	 float inv_norm = 1.0f / buf_norm;
964	 auto X = buf * inv_norm;
965	
966	 // Muon's Newton-Schulz orthogonalization (X.t(), mm) and the
967	 // 0.2*sqrt(max(rows,cols)) RMS scale are defined only for a 2D
968	 // matrix param. A 1D bias or a 3D/4D conv weight would silently read
969	 // p.size(1) as a wrong dimension (or be undefined for dim<2) and
970	 // corrupt the update. The Python Muon optimizer routes non-2D params
971	 // to the AdamW path (fused_adamw_simple_step); enforce that contract
972	 // loudly here so a misrouted param fails instead of corrupting.
973	 TORCH_CHECK(p.dim() == 2, "muon_fused_step: param ", i,
974	 " has ndim=", p.dim(),
975	 " but the Newton-Schulz orthogonalization requires a 2D "
976	 "matrix. Route 1D/>=3D params to the AdamW path "
977	 "(fused_adamw_simple_step) in the Python wrapper.");
978	 int64_t rows = p.size(0);
979	 int64_t cols = p.size(1);
980	 float max_dim = static_cast<float>(std::max(rows, cols));
981	 float scale_factor = 0.2f * std::sqrt(max_dim);
982	 float neg_lr_scale = -lr * scale_factor;
983	 float decay_factor = 1.0f - lr * wd;
984	
985	 // Double-buffer the NS combine output: allocate one scratch of X's shape
986	 // up front and ping-pong into it across iterations, instead of a fresh
987	 // torch::empty_like(X) every intermediate step. The combine launcher reads
988	 // X and writes a distinct buffer, so two buffers suffice; we swap handles
989	 // (no copies). Math is unchanged.
990	 torch::Tensor scratch; // lazily allocated on first combine step
991	 for (int step = 0; step < ns_steps; step++) {
992	 auto A = torch::mm(X, X.t());
993	 auto AX = torch::mm(A, X);
994	 auto AAX = torch::mm(A, AX);
995	 if (step < ns_steps - 1) {
996	 if (!scratch.defined()) scratch = torch::empty_like(X);
997	 SG_DISPATCH_CALL(launch_muon_ns_combine,
998	 scratch, X, AX, AAX, NS_A, NS_B, NS_C);
999	 // Ping-pong: the just-read X becomes the next iteration's scratch,
1000	 // the freshly-written buffer becomes X.
1001	 std::swap(X, scratch);
1002	 } else {
1003	 SG_DISPATCH_CALL(launch_muon_ns_combine_update_fused,
1004	 p, X, AX, AAX, NS_A, NS_B, NS_C,
1005	 neg_lr_scale, decay_factor);
1006	 }
1007	 }
1008	 if (ns_steps == 0) {
1009	 auto X_typed = X.to(p.dtype());
1010	 SG_DISPATCH_CALL(launch_muon_update,
1011	 p, X_typed, neg_lr_scale, decay_factor);
1012	 }
1013	 }
1014	}
