1339	void supergrok11_fused_step(
1340	 std::vector<torch::Tensor>& params,
1341	 std::vector<torch::Tensor>& grads,
1342	 std::vector<torch::Tensor>& exp_avgs,
1343	 std::vector<torch::Tensor>& exp_avg_sqs,
1344	 std::vector<torch::Tensor>& mus,
1345	 std::vector<torch::Tensor>& sharpness_cache,
1346	 std::vector<int64_t>& steps,
1347	 std::vector<float>& layer_alphas,
1348	 std::vector<float>& layer_beta1s,
1349	 torch::Tensor W1, torch::Tensor b1,
1350	 torch::Tensor W2, torch::Tensor b2,
1351	 float rescale, int hidden_dim,
1352	 float beta2, float lr, float wd_eff, float eps,
1353	 float lamb, float ramp, float gate_temperature,
1354	 float grad_clip_norm
1355	) {
1356	 const size_t n_params = params.size();
1357	 check_params_grads(params, grads, "supergrok11_fused_step");
1358	 check_list_len(exp_avgs, n_params, "exp_avgs", "supergrok11_fused_step");
1359	 check_list_len(exp_avg_sqs, n_params, "exp_avg_sqs", "supergrok11_fused_step");
1360	 check_list_len(mus, n_params, "mus", "supergrok11_fused_step");
1361	 check_list_len(sharpness_cache, n_params, "sharpness_cache", "supergrok11_fused_step");
1362	 check_list_len(steps, n_params, "steps", "supergrok11_fused_step");
1363	 check_list_len(layer_alphas, n_params, "layer_alphas", "supergrok11_fused_step");
1364	 check_list_len(layer_beta1s, n_params, "layer_beta1s", "supergrok11_fused_step");
1365	 clip_grad_norms_device_side(grads, n_params, grad_clip_norm);
1366	
1367	 for (size_t i = 0; i < n_params; i++) {
1368	 if (!grads[i].defined() || grads[i].numel() == 0) continue;
1369	 // steps[i] is pre-incremented by the Python optimizer (SuperGrok11.step):
1370	 // pybind passes `steps` by value, so incrementing it here would NOT persist
1371	 // back to Python and would freeze bias-correction at t=1. Read it as-is.
1372	 float alpha = layer_alphas[i];
1373	 float beta1 = layer_beta1s[i];
1374	 float bc1 = 1.0f - std::pow(beta1, static_cast<float>(steps[i]));
1375	 float bc2 = 1.0f - std::pow(beta2, static_cast<float>(steps[i]));
1376	
1377	 // Canonical SuperGrok v1.1 mixing (csrc/algorithms/supergrok11.h:101,
1378	 // Pallas ref launch_supergrok11.py, oracle ref_sg11_step):
1379	 //   gate       = clamp(cosine(grad, mu), 0, 1)
1380	 //   smart_grad = grad + lamb_eff * mu                  (applied ONCE)
1381	 //   AdamW on smart_grad.
1382	 // The base correction (1-gate)*alpha SHRINKS as grad/mu alignment (gate)
1383	 // grows — the polarity that lets a memorized solution HOLD. We reproduce this
1384	 // through the existing kernels by exact algebra, WITHOUT any kernel signature
1385	 // change:
1386	 //   * mu_metanet with alpha=0 writes mu = rescale*phi (mu is independent of
1387	 //     alpha, kernel line ~285) AND its smart_grad output = grad + 0*mu = grad.
1388	 //   * dispatch_cosine_gate(smart_grad==grad, mu) is therefore cosine(grad, mu).
1389	 //   * adam_decay computes g_eff = smart_grad + lamb_eff*mu; with
1390	 //     smart_grad==grad and the lamb_eff below this is the single live add,
1391	 //     then the canonical Adam tail.
1392	 //
1393	 // OWNER DECISION (Option B): `lamb`/`ramp` are made LIVE as MULTIPLIERS on the
1394	 // single canonical term. The pre-fix code had a SECOND mu add
1395	 // `ramp*gate*lamb*mu` (the OLD comment: "they were the buggy SECOND mu add …
1396	 // whose coefficient GREW with the gate and destroyed the memorized solution");
1397	 // that second add was REMOVED as a collapse mitigation, which suppressed the
1398	 // lamb/ramp mechanism entirely (they were (void)-ed). It is RESTORED here
1399	 // MULTIPLICATIVELY on the ONE live, correctly-shrinking term:
1400	 //   lamb_eff = ramp * lamb * (1 - gate) * alpha
1401	 // so lamb=1.0 with post-warmup ramp=1.0 reproduces the previous behavior
1402	 // EXACTLY ((1-gate)*alpha), while lamb is a genuine tuner dial that scales the
1403	 // correction WITHOUT flipping its polarity (it still shrinks as the gate
1404	 // grows). ramp is the warmup schedule (0 during warmup → no correction early).
1405	 const float lamb_eff_scale = ramp * lamb;
1406	 auto smart_grad = torch::empty_like(params[i]);
1407	 SG_DISPATCH_CALL(launch_sg11_mu_metanet,
1408	 mus[i], grads[i], sharpness_cache[i], smart_grad, /*alpha=*/0.0f,
1409	 W1, b1, W2, b2, rescale, hidden_dim);
1410	
1411	 float gate = dispatch_cosine_gate(smart_grad, mus[i], gate_temperature);
1412	 float lamb_eff = lamb_eff_scale * (1.0f - gate) * alpha;
1413	
1414	 SG_DISPATCH_CALL(launch_sg11_adam_decay,
1415	 params[i], exp_avgs[i], exp_avg_sqs[i], smart_grad, mus[i],
1416	 lamb_eff, beta1, beta2, lr, wd_eff, eps, bc1, bc2);
1417	 }
1418	}
