1512	void supergrok15_fused_step(

1203	std::tuple<float, float, float> prodigy_fused_step(
1204	 std::vector<torch::Tensor>& params,
1205	 std::vector<torch::Tensor>& grads,
1206	 std::vector<torch::Tensor>& exp_avgs,
1207	 std::vector<torch::Tensor>& exp_avg_sqs,
1208	 std::vector<torch::Tensor>& s_bufs,
1209	 std::vector<torch::Tensor>& param_inits,
1210	 std::vector<int64_t>& steps,
1211	 float d_lr,
1212	 float r_ema, float s_ema,
1213	 float beta1, float beta2, float beta3, float lr, float wd,
1214	 float eps, float d0, float d_coef
1215	) {
1216	 if (params.empty()) return std::make_tuple(d_lr, r_ema, s_ema);
1217	 check_params_grads(params, grads, "prodigy_fused_step");
1218	 {
1219	 const size_t n = params.size();
1220	 check_list_len(exp_avgs, n, "exp_avgs", "prodigy_fused_step");
1221	 check_list_len(exp_avg_sqs, n, "exp_avg_sqs", "prodigy_fused_step");
1222	 check_list_len(s_bufs, n, "s_bufs", "prodigy_fused_step");
1223	 check_list_len(param_inits, n, "param_inits", "prodigy_fused_step");
1224	 check_list_len(steps, n, "steps", "prodigy_fused_step");
1225	 }
1226	
1227	 torch::Device dev(torch::kCPU);
1228	 for (auto& g : grads) {
1229	 if (g.defined() && g.numel() > 0) { dev = g.device(); break; }
1230	 }
1231	
1232	 std::vector<torch::Tensor> vp, vg, vpi, vea, veasq, vs;
1233	 std::vector<float> bc1_vec, bc2_vec;
1234	 for (size_t i = 0; i < params.size(); i++) {
1235	 if (!grads[i].defined() || grads[i].numel() == 0) continue;
1236	 float bc1 = 1.0f - std::pow(beta1, static_cast<float>(steps[i]));
1237	 float bc2 = 1.0f - std::pow(beta2, static_cast<float>(steps[i]));
1238	 vp.push_back(params[i]); vg.push_back(grads[i]);
1239	 vpi.push_back(param_inits[i]);
1240	 vea.push_back(exp_avgs[i]); veasq.push_back(exp_avg_sqs[i]);
1241	 vs.push_back(s_bufs[i]);
1242	 bc1_vec.push_back(bc1); bc2_vec.push_back(bc2);
1243	 }
1244	 if (vp.empty()) return std::make_tuple(d_lr, r_ema, s_ema);
1245	
1246	 auto d_lr_buf = torch::tensor(
1247	 {d_lr}, torch::TensorOptions().device(dev).dtype(torch::kFloat32));
1248	 // Persistent EMA numerator/denominator carried in/out as device scalars,
1249	 // seeded from the Python-held floats. The launcher decays each by beta3 and
1250	 // adds this step's reduction (d0 is a global constant that cancels in the
1251	 // ratio, so it is NOT threaded into the device math — the bare d²·<g,p0−p>
1252	 // and d²·‖g‖₁ partials already match prodigyopt up to that constant factor).
1253	 auto r_num_buf = torch::tensor(
1254	 {r_ema}, torch::TensorOptions().device(dev).dtype(torch::kFloat32));
1255	 auto s_den_buf = torch::tensor(
1256	 {s_ema}, torch::TensorOptions().device(dev).dtype(torch::kFloat32));
1257	 (void)d0;
1258	
1259	 SG_DISPATCH_CALL(launch_multi_tensor_prodigy_fused_reduce_step,
1260	 vp, vg, vpi, vea, veasq, vs, bc1_vec, bc2_vec, d_lr_buf,
1261	 r_num_buf, s_den_buf,
1262	 beta1, beta2, beta3, lr, wd, eps, d_coef);
1263	 return std::make_tuple(
1264	 d_lr_buf.item<float>(), r_num_buf.item<float>(), s_den_buf.item<float>());
1265	}
