227	// =========================================================================
228	//  The L3/L1 persistent megakernel. ONE launch composes the real model stages
229	//  (L3 only) and the real optimizer tail, separated by the hand-built grid
230	//  barrier (§1.4) whose last arriver resets the task-queue counter race-free.
231	//  Launch config (host): gridDim.x = #SMs, blockDim.x = 256 = TWO Hopper
232	//  warp-groups (§3.4). Warp-group 0 (threads 0..127) is the producer and
233	//  deallocs its register file down to kProducerRegsF; warp-group 1 (threads
234	//  128..255) is the consumer and allocs up to kConsumerRegsF. setmaxnreg is
235	//  warp-group-uniform, so the call is issued by all 128 lanes of each group.
236	//
237	//  Behavior-preserving: setmaxnreg only repartitions the SM register file
238	//  between the two warp-groups; it does NOT change any computed value. All 256
239	//  threads still execute the same grid-stride element-local stages (whose
240	//  shared reduction / staging buffers are sized for 256), so __syncthreads is
241	//  well-formed and the results are identical to the single-warp-group launch.
242	// =========================================================================
243	template <ModelId M, OptId Opt, FuseTier Tier>
244	__global__ void __launch_bounds__(kFusedBlockThreads)
245	fused_megakernel(PersistentContext ctx,
246	                 float* __restrict__ params,
247	                 const float* __restrict__ input,
248	                 float* __restrict__ acts,
249	                 float* __restrict__ grad,
250	                 const int* __restrict__ sizes,
251	                 const int* __restrict__ offsets,
252	                 float lr, int step, FusedOptState st) {
253	    GridBarrier bar = ctx.barrier();
254	
255	    // §3.4 warp-group register repartition: producer WG (0) gives registers
256	    // back; consumer WG (1) claims the large file. Uniform within each WG.
257	    const int warp_group = threadIdx.x / kWarpGroupThreads;
258	    if (warp_group == 0) {
259	        wgs::warpgroup_reg_dealloc<kProducerRegsF>();
260	    } else {
261	        wgs::warpgroup_reg_alloc<kConsumerRegsF>();
262	    }
263	
264	    if constexpr (Tier == FuseTier::L3) {
265	        // ── Phase 1: real model forward (writes acts to global; see the Stage 5
266	        //    note above for why acts stays global across the fwd→bwd barrier). ─
267	        // #4: the task-queue reset for the NEXT phase is folded into the grid
268	        // barrier's last-arriver critical section (sync_reset). The reset lands
269	        // before the generation bump, so every CTA crossing into the fused
270	        // backward+optimizer phase sees a zeroed counter.
271	        model_forward_stage<M>(ctx, params, input, acts, sizes, offsets);
272	        bar.sync_reset(ctx.g_next_task);
273	        // ── Phase 2 (Stage 5 TRUE FUSION): backward + optimizer in ONE pass,
274	        //    grad held in a SMEM tile (no global grad round-trip), with the
275	        //    bwd→opt grid barrier eliminated (see fused_backward_optimizer_stage).
276	        st.lr = lr;
277	        fused_backward_optimizer_stage<M, Opt>(ctx, params, acts, sizes,
278	                                               offsets, step, st);
279	        // grad (param) unused on the L3 path now — the grad is SMEM-resident.
280	        (void)grad;
281	    } else {
282	        // ── L1: model fwd/bwd are the framework's own launches; this kernel is
283	        //    the fused optimizer tail only (reads grad from global). ───────────
284	        st.lr = lr;
285	        fused_optimizer_stage<Opt>(ctx, params, grad, sizes, offsets, step, st);
286	    }
287	}
288	
289	// =========================================================================
290	//  Host launcher — one persistent CTA per SM, 256 threads/CTA (2 warp-groups).
291	//
292	//  HANG-FREEDOM (Stage 1 fix) — the L3 kernel rendezvouses ALL launched CTAs at
293	//  GridBarrier::sync_reset, which spins until exactly ctx.n_ctas CTAs arrive.
294	//  With an ordinary <<<>>> launch that has NO co-residency guarantee: if the
295	//  kernel's per-SM occupancy is < 1 block (register/smem pressure — the L3 cells
296	//  run ~168 regs / ~65 KB smem), some of the gridDim.x==#SMs CTAs never become
297	//  resident, never arrive, and the resident CTAs spin FOREVER. (cudaLaunch
298	//  Cooperative would error -1 in that case, but the plain launch just hangs.)
299	//
300	//  MECHANISM CHOSEN: occupancy-capped grid + co-residency assert (mechanism (a)
301	//  in the task). We query cudaOccupancyMaxActiveBlocksPerMultiprocessor for THIS
302	//  exact kernel instantiation at the launch block size and cap gridDim.x to
303	//  (occ_blocks_per_sm * #SMs) — but, because every persistent CTA must hold a
304	//  full warm optimizer-state slice and we pin ONE per SM (§1.3), we launch
305	//  exactly min(#SMs, occ * #SMs) == #SMs ONLY WHEN occ >= 1. If the kernel
306	//  cannot place even one block per SM (occ == 0) we REFUSE to launch (return
307	//  cudaErrorLaunchOutOfResources) instead of hanging. The assert documents the
308	//  invariant in debug builds; the runtime check enforces it in release builds.
309	//  We deliberately keep at most 1 CTA/SM resident (the §1.3 pin) so the barrier
310	//  set size equals the number of co-resident CTAs — never more than can fit.
311	//
312	//  This is preferred over cudaLaunchCooperativeKernel here because (a) it needs
313	//  no kernel attribute / driver cooperative-launch capability probe, (b) it
314	//  preserves the existing reusable hand-built GridBarrier (§1.4) which is the
315	//  whole point of NOT requiring a cooperative grid, and (c) it is fully compile-
316	//  checkable without silicon. The barrier counters (g_arrived / g_generation)
317	//  and the task counter (g_next_task) are device-zeroed before each launch so a
318	//  stale generation/arrival from a prior step can never desync the rendezvous.
319	// =========================================================================
320	template <ModelId M, OptId Opt, FuseTier Tier>
321	cudaError_t launch_fused_megakernel(
322	        PersistentContext ctx,
323	        float* params, const float* input, float* acts, float* grad,
324	        const int* sizes, const int* offsets,
325	        float lr, int step, FusedOptState st, cudaStream_t stream) {
326	    int dev = 0;
327	    cudaError_t err = cudaGetDevice(&dev);
328	    if (err != cudaSuccess) return err;
329	    int n_sms = 0;
330	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
331	    if (err != cudaSuccess) return err;
332	
333	    // Co-residency guarantee: how many blocks of THIS kernel actually fit on one
334	    // SM at the launch block size? If < 1, the grid barrier could never complete
335	    // (a non-resident CTA never arrives) — so we must NOT launch a gridDim that
336	    // relies on a CTA that cannot be placed.
337	    int occ_blocks_per_sm = 0;
338	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
339	        &occ_blocks_per_sm,
340	        (const void*)&fused_megakernel<M, Opt, Tier>,
341	        kFusedBlockThreads, /*dynamicSMemBytes=*/0);
342	    if (err != cudaSuccess) return err;
343	    // Hang-freedom invariant: at least one block per SM must be resident, or the
344	    // GridBarrier rendezvous of n_ctas CTAs can never be satisfied.
345	    assert(occ_blocks_per_sm >= 1 &&
346	           "fused_megakernel: 0 blocks/SM occupancy — GridBarrier would hang; "
347	           "reduce register/smem footprint or this cell must run L1 (no grid "
348	           "barrier).");
349	    if (occ_blocks_per_sm < 1) {
350	        // Release-build enforcement: refuse rather than hang.
351	        return cudaErrorLaunchOutOfResources;
352	    }
353	
354	    // §1.3: pin exactly ONE persistent CTA per SM (keeps each SM's optimizer-
355	    // state slice L2-warm). occ>=1 guarantees that single CTA per SM is co-
356	    // resident, so all n_sms CTAs rendezvous at the barrier — no hang.
357	    const unsigned launch_ctas = (unsigned)n_sms;
358	    ctx.n_ctas = launch_ctas;
359	
360	    // Device-zero the barrier + task counters before EACH launch so no stale
361	    // generation/arrival from a prior step can desync the rendezvous (the
362	    // GridBarrier reuse argument in megakernel_common.cuh assumes a zeroed start).
363	    if (ctx.g_arrived != nullptr) {
364	        err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream);
365	        if (err != cudaSuccess) return err;
366	    }
367	    if (ctx.g_generation != nullptr) {
368	        err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream);
369	        if (err != cudaSuccess) return err;
370	    }
371	    if (ctx.g_next_task != nullptr) {
372	        err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream);
373	        if (err != cudaSuccess) return err;
374	    }
375	
376	    // 256 threads = two Hopper warp-groups for the §3.4 producer/consumer
377	    // register split (kProducerRegsF / kConsumerRegsF).
378	    dim3 grid(launch_ctas), block(kFusedBlockThreads);
379	    fused_megakernel<M, Opt, Tier><<<grid, block, 0, stream>>>(
380	        ctx, params, input, acts, grad, sizes, offsets, lr, step, st);
381	    return cudaGetLastError();
382	}
383	
384	}}} // namespace sg::fused::sm90
