// .cuh:275-286) — sg == grad (the alpha=0 mu_metanet makes smart_grad==grad,
// bindings.cpp:1408). gate_temp is IGNORED (the function ignores it).
//
// `off`/`n` identify the tensor slice; call this from within the per-tensor body
// (the SAME CTA that produced this tensor's mu). The returned gate feeds
// st.gate for apply_optimizer<SuperGrok11>.
__device__ inline float sg11_precompute_gate_for_tensor(
        const float* __restrict__ grad, const float* __restrict__ mu_blob,
        int64_t off, int n) {
    float num = 0.0f, den_g = 0.0f, den_m = 0.0f;
    for (int i = threadIdx.x; i < n; i += blockDim.x) {
        const int64_t gi = off + i;
        const float sg = grad[gi];      // smart_grad == grad (alpha=0 path)
        const float u  = mu_blob[gi];
        num   += sg * u;
        den_g += sg * sg;
        den_m += u  * u;
