    // reductions (the live host fn does three independent .sum()s — same).
    num   = prim::block_reduce_sum_f32(num);
    __syncthreads();
    den_g = prim::block_reduce_sum_f32(den_g);
    __syncthreads();
    den_m = prim::block_reduce_sum_f32(den_m);
