    // sqrt(den_g*den_m + 1e-12); gate = (denom>0)? num/denom : 0; clamp[0,1].
    const float denom = sqrtf(den_g * den_m + 1e-12f);
    const float gate = (denom > 0.0f) ? (num / denom) : 0.0f;
    return fminf(fmaxf(gate, 0.0f), 1.0f);
}

