//  phases; the codegen (NOT this header) owns the barriers, exactly as
//  fused_megakernel.cuh interleaves model stages with bar.sync_reset. This
//  dispatcher therefore exposes the FIRST (pre-barrier) phase as the canonical
//  "stage" and documents the remaining phases the caller must drive. For the
//  per-tensor-only stages (SG11 mu, SG15 mu) the whole precompute is single-
//  phase (no grid barrier) and runs here in full; the SG11 gate is computed
//  per-tensor by the apply driver via sg11_precompute_gate_for_tensor.
//
//  A NOTHING-NEEDED / MODEL-COUPLED / SKIP optimizer must NOT be instantiated
//  here (static_assert guards it) — its tail already runs complete, or its input
//  comes from the model stage.
// ============================================================================
template <OptId Opt>
__device__ inline void optimizer_precompute_stage(
        const PersistentContext& ctx,
        float* __restrict__ params,
        const float* __restrict__ grad,
        const int* __restrict__ sizes, const int* __restrict__ offsets,
        const FusedOptState& st,
        PrecomputeWorkspace ws,
        // Optional model-coupled / meta inputs (sharpness, phi weights, init).
        const float* __restrict__ param_init = nullptr,
        const float* __restrict__ sharpness = nullptr,
        const float* __restrict__ phi_W1 = nullptr,
        const float* __restrict__ phi_b1 = nullptr,
        const float* __restrict__ phi_W2 = nullptr,
        float phi_b2 = 0.0f, float rescale = 1.0f) {
    static_assert(optimizer_needs_precompute<Opt>::value,
        "optimizer_precompute_stage instantiated for an optimizer that needs no "
        "precompute (grokfast/grokadamw/neuralgrok: math is in apply), is model-"
        "coupled (looksam: sam_dir from a 2nd backward), or is sibling-owned "
        "(supergrok2). See the verdict table at the top of this header.");

    if constexpr (Opt == OptId::Prodigy) {
        // Phase A only (caller grid-barriers, then calls
        // prodigy_precompute_reduce_phaseB). param_init is the trajectory anchor.
        prodigy_precompute_reduce_phaseA(ctx, params, param_init, grad,
                                         sizes, offsets, st.d_factor, ws);
    } else if constexpr (Opt == OptId::SuperGrok11) {
        // Single-phase per-tensor mu; the gate is computed in the apply driver.
        sg11_precompute_mu_stage<kSGMetaHidden>(
            ctx, st.mu, grad, sharpness, sizes, offsets,
            phi_W1, phi_b1, phi_W2, phi_b2, rescale);
    } else if constexpr (Opt == OptId::SuperGrok15) {
        sg15_precompute_mu_stage<kSGMetaHidden>(
            ctx, st.mu, grad, sharpness, sizes, offsets,
            phi_W1, phi_b1, phi_W2, phi_b2, rescale);
