        // muon_norm_reduce_phaseB → barrier → muon_scale_X → (ns_steps ×
        // {muon_matmul ×3 with barriers → muon_ns_combine_phase}) per matrix,
        // looping matrices. Exposed as the explicit phase fns above, not foldable
        // into this single call — see INTEGRATION-OPTSTAGES.md.
        (void)params; (void)grad; (void)sizes; (void)offsets; (void)st; (void)ws;
    }
    (void)param_init; (void)sharpness; (void)phi_W1; (void)phi_b1; (void)phi_W2;
    (void)phi_b2; (void)rescale;
}

